    featured_image_url: "/api/og?title=Salary%20Slip%20Calculation%20FY%202025%E2%80%9326&subtitle=New%20Tax%20Regime%2C%20Standard%20Deduction%20%26%20EPF%20Rules&type=blog",
    published: true,
    published_at: "2026-09-27T06:00:00+00:00",
    author_name: "Kagazo Tax & Payroll Research Desk",
    created_at: "2026-09-27T06:00:00+00:00",
    updated_at: "2026-09-27T06:00:00+00:00",
    lang: "en",
    hreflang_group: "salary-slip-calculation-format-fy-2025-26-new-tax-regime-guide",
